"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[8296],{48296:a=>{a.exports=JSON.parse('{"meta":{"title":"Niyyah: Jadikan Niat Langkah Kecil yang Istiqamah - iMuslim Life","description":"Niyyah menukar niat menjadi pelan 7 hari yang terikat pada waktu solat anda, dan Gema Al-Quran mencari petikan Al-Quran yang disemak ulama untuk isi hati anda. Percuma, tanpa iklan."},"periods":{"fajr":"Subuh","dhuhr":"Zohor","asr":"Asar","maghrib":"Maghrib","isha":"Isyak"},"hero":{"eyebrow":"Niyyah","h1":"Jadikan niat satu langkah <g>kecil yang istiqamah</g>.","lede":"Lima soalan lembut menjadi pelan tujuh hari yang dijalin dengan solat yang sudah anda dirikan. Dan apabila hati terasa berat, Gema Al-Quran mencari ayat-ayat yang menyapanya.","begin":"Mula, bismillah","tryEchoes":"Cuba Gema Al-Quran","facts":"Percuma \xb7 Tanpa iklan \xb7 Disemak ulama \xb7 Berfungsi dalam pelayar anda","scroll":"Tatal: satu hari, dari Subuh ke Isyak","alt":"Niyyah: gerbang mihrab dengan Basmalah di bawah langit malam"},"hadith":{"text":"\u201cSesungguhnya setiap amalan itu bergantung pada niat.\u201d","src":"Sahih al-Bukhari 1 \xb7 Sahih Muslim 1907"},"steps":[{"t":"Niat","d":"Pilih apa yang ingin anda suburkan: sabar, dekat dengan Al-Quran, syukur, lemah lembut di rumah."},{"t":"Amalan","d":"Satu langkah kecil, dua hingga lima belas minit. Cukup kecil untuk dikekalkan pada hari paling sukar anda."},{"t":"Waktu","d":"Terikat pada solat yang sudah anda dirikan, mengikut waktu solat anda sendiri, jadi ia berubah mengikut musim."},{"t":"Renungan","d":"Semakan lembut pada hari ketiga dan ketujuh. Waktu tidak sesuai? Terlalu banyak? Ia diselaraskan dalam beberapa saat."}],"effortNote":"Menyempurnakan rutin ialah usaha di pihak kita. Penerimaan dan hasilnya milik Allah. Pelan ini alat bantu, bukan ukuran iman anda.","try":{"eyebrow":"Gema Al-Quran \xb7 cuba sekarang","h2":"Apa yang ada di <e>hati</e> anda?","lede":"Tulis satu baris tentang apa yang anda hadapi, dalam bahasa Inggeris, Urdu, Urdu rumi atau Arab. Niyyah menjawab dengan petikan daripada indeks yang disemak ulama dan satu soalan untuk direnungkan. Tanpa log masuk. Tiada apa yang anda taip disimpan.","inputLabel":"Ceritakan keadaan anda","listening":"Mendengar\u2026","find":"Cari petikan","failed":"Gema Al-Quran tidak dapat dihubungi sekarang. Ia berada di <a>alexa.imuslimlife.com/niyyah</a>, sila cuba di sana.","crisisH":"Sila hubungi seseorang sekarang.","crisisP":"Apa yang anda ceritakan kedengaran serius, dan anda layak mendapat sokongan sebenar daripada seseorang.","rulingEyebrow":"Ini memerlukan ulama","rulingH":"Soalan hukum memerlukan orang yang berkelayakan.","rulingP":"Niyyah tidak pernah memberi fatwa. Imam yang mengenali keadaan anda boleh menjawab dengan tepat.","none":"Belum ada padanan yang dekat. Cuba tambah beberapa perkataan tentang perasaan anda atau apa yang anda hadapi.","surah":"Surah","tafsir":"Tafsir","plan":"Jadikan pelan 7 hari","missThanks":"Terima kasih, itu membantu kami menambah baik. Cuba huraikan dengan perkataan lain.","miss":"Bukan itu maksud saya","shared":"Dikongsi, terima kasih. Ia membantu menambah baik Gema Al-Quran.","share":"Kongsi soalan ini (tanpa nama anda) untuk membantu menambah baik Gema Al-Quran.","example":"Satu contoh","exampleQ":"Bilakah kali terakhir zikir kepada Allah memberi anda ketenangan?","exampleSrc":"Ar-Ra\'d 13:28 \xb7 Terjemahan makna: Abdullah Muhammad Basmeih. Teks Arab: Tanzil Uthmani.","examples":["I keep losing my temper with my kids","mujhe bohat ghussa aata hai","I feel guilty, will Allah forgive me?","My father passed away and it feels heavy","I\u2019m anxious about money and the future"],"placeholder":"For example: I get impatient with my children in the evenings"},"ayah":{"en":"\\"(Iaitu) orang-orang yang beriman dan tenang tenteram hati mereka dengan zikrullah\\". Ketahuilah dengan \\"zikrullah\\" itu, tenang tenteramlah hati manusia.","src":"Ar-Ra\'d 13:28 \xb7 Terjemahan makna: Abdullah Muhammad Basmeih"},"week":{"eyebrow":"Minggu anda","h2":"Setiap hari anda hadir, <e>sekuntum mawar mekar</e>.","lede":"Tiada rentetan untuk terputus, tiada rasa bersalah. Hari yang terlepas kekal sebagai kudup dan pelan bersambung esok. Langit berubah mengikut waktu solat anda, dari merah jambu Subuh ke bintang Isyak.","label":"Seminggu mawar: lima hari mekar","shots":["Hari ini, waktu Isyak","Pelan 7 hari anda","Hari yang sama, waktu Zohor"]},"care":{"eyebrow":"Dibina dengan teliti","h2":"Boleh dipercayai <e>sejak reka bentuknya</e>.","items":[{"t":"Disemak ulama","d":"Setiap petikan, amalan kecil dan soalan disemak dan diluluskan sebelum sesiapa melihatnya."},{"t":"Bukan fatwa","d":"Soalan hukum dirujuk dengan lembut kepada ulama yang berkelayakan. Niyyah tidak pernah memutuskan hukum."},{"t":"Tiada rekaan","d":"Tiada AI menulis teks agama di sini. Petikan ialah Al-Quran itu sendiri, dengan terjemahan yang dinyatakan sumbernya."},{"t":"Selamat","d":"Perkataan tentang bahaya memaparkan talian bantuan dahulu, bukan petikan."},{"t":"Peribadi","d":"Catatan anda milik anda seorang. Padam semuanya dengan satu sentuhan."},{"t":"Percuma, selamanya","d":"Tanpa iklan, tanpa langganan. Sedekah jariah, insya-Allah."}]},"faq":{"eyebrow":"Soalan","h2":"Baik untuk <e>diketahui</e>.","items":[{"q":"Apakah maksud \u201cNiyyah\u201d?","a":"Niyyah (\u0646\u0650\u064a\u064e\u0651\u0629) bermaksud niat. \u201cSesungguhnya setiap amalan itu bergantung pada niat\u201d (Sahih al-Bukhari 1). Niyyah membantu niat menjadi amalan kecil yang istiqamah."},{"q":"Perlukah saya akaun?","a":"Tiada akaun diperlukan untuk mencuba Gema Al-Quran. Untuk menyimpan pelan, menanda hari anda hadir dan menyimpan petikan, log masuk dengan Amazon, sama seperti Muslim Companion for Alexa."},{"q":"Bahasa apa yang difahami?","a":"Inggeris, Urdu, Urdu rumi (seperti \u201cmujhe bohat ghussa aata hai\u201d) dan Arab. Petikan dipaparkan dalam bahasa Arab dengan terjemahan Inggeris atau Urdu."},{"q":"Adakah ia pengganti ulama atau kaunselor?","a":"Tidak. Niyyah menawarkan petikan untuk direnungkan dan langkah kecil untuk dilakukan. Untuk hukum, tanyalah ulama yang berkelayakan; pada masa sukar, hubungi orang yang anda percayai atau talian bantuan."},{"q":"Di mana ia berfungsi?","a":"Dalam mana-mana pelayar pada telefon, tablet atau komputer anda, di alexa.imuslimlife.com/niyyah."}]},"final":{"h2":"Mulakan dengan langkah <g>kecil</g>.","lede":"Pelan pertama anda mengambil masa seminit. Semoga Allah memudahkannya dan menerimanya daripada anda.","alexa":"Muslim Companion for Alexa"}}')}}]);